// dev-logs-v1.0 · POST /api/dev/log-evento
// Recebe um LOTE de eventos do HTML e guarda num buffer circular em memória (flow context). Não toca PLC/DB2100.
const FLOW = 'dev-logs-v1.0';
const MAX = 5000;        // eventos guardados (os mais antigos saem e entram em 'descartados')
const MAX_LOTE = 200;    // eventos por POST
const MAX_STR = 400;     // tamanho máximo de cada texto
const MAX_OBJ = 1500;    // tamanho máximo (JSON) de det / est
const H = { 'Content-Type': 'application/json' };

const erro = (st, txt) => { msg.statusCode = st; msg.headers = H; msg.payload = { ok: false, flow: FLOW, erro: txt }; return msg; };
const b = msg.payload;
if (!b || typeof b !== 'object' || !Array.isArray(b.eventos)) return erro(400, 'corpo invalido: esperado {"eventos":[...]}');
if (b.eventos.length > MAX_LOTE) return erro(400, 'lote grande demais (max ' + MAX_LOTE + ' eventos)');

const str = (v, n) => { v = (v === null || v === undefined) ? '' : String(v); return v.length > n ? v.slice(0, n - 1) + '…' : v; };
const obj = (o) => {
  if (o === null || o === undefined) return null;
  if (typeof o !== 'object') return str(o, MAX_STR);
  let s; try { s = JSON.stringify(o); } catch (e) { return null; }
  if (s.length <= MAX_OBJ) return JSON.parse(s);
  return { _truncado: s.slice(0, MAX_OBJ - 1) + '…' };
};

let boot = flow.get('devlog_boot');
if (!boot) { boot = Date.now().toString(36) + Math.random().toString(36).slice(2, 6); flow.set('devlog_boot', boot); }
const ev = flow.get('devlog_ev') || [];
const ult = flow.get('devlog_ult') || {};      // sessao -> maior n já aceito (evita duplicar em reenvio)
let seq = flow.get('devlog_seq') || 0;
let drop = flow.get('devlog_drop') || 0;
let aceitos = 0, dup = 0, inval = 0;
const rx = new Date().toISOString();

for (const e of b.eventos) {
  if (!e || typeof e !== 'object' || typeof e.sessao !== 'string' || typeof e.n !== 'number' || !isFinite(e.n)) { inval++; continue; }
  if ((ult[e.sessao] || 0) >= e.n) { dup++; continue; }
  ult[e.sessao] = e.n;
  seq++;
  ev.push({
    seq: seq, rx: rx,
    sessao: str(e.sessao, 40), n: e.n, t: str(e.t, 30), ms: (typeof e.ms === 'number' ? e.ms : null), v: str(e.v, 20),
    modo: str(e.modo, 20), card: str(e.card, 20), tipo: str(e.tipo, 20), acao: str(e.acao, MAX_STR), res: str(e.res, 12),
    det: obj(e.det), est: obj(e.est)
  });
  aceitos++;
}
if (ev.length > MAX) { const extra = ev.length - MAX; ev.splice(0, extra); drop += extra; }
const ks = Object.keys(ult);
if (ks.length > 50) delete ult[ks[0]];           // no máximo 50 sessões lembradas

flow.set('devlog_ev', ev); flow.set('devlog_ult', ult); flow.set('devlog_seq', seq); flow.set('devlog_drop', drop);
msg.statusCode = 200; msg.headers = H;
msg.payload = { ok: true, flow: FLOW, boot: boot, recebidos: b.eventos.length, aceitos: aceitos, duplicados: dup, invalidos: inval, ultimoSeq: seq, guardados: ev.length };
return msg;

// dev-logs-v1.0 · GET /api/dev/logs?desde=<seq>&limit=<n>
// Devolve os eventos com seq > desde em ORDEM CRESCENTE (o cliente avança o cursor sem buracos); sem 'desde' = os 'limit' últimos.
const FLOW = 'dev-logs-v1.0';
const q = (msg.req && msg.req.query) || {};
const limit = Math.min(Math.max(parseInt(q.limit, 10) || 500, 1), 2000);
const desde = parseInt(q.desde, 10);
let boot = flow.get('devlog_boot');
if (!boot) { boot = Date.now().toString(36) + Math.random().toString(36).slice(2, 6); flow.set('devlog_boot', boot); }
const ev = flow.get('devlog_ev') || [];
const seq = flow.get('devlog_seq') || 0;
const drop = flow.get('devlog_drop') || 0;
let out, truncado = false, perdidos = 0;
if (!isNaN(desde)) {
  const prim = ev.length ? ev[0].seq : seq + 1;
  if (desde < prim - 1) perdidos = prim - 1 - desde;          // o buffer já descartou eventos que o cliente não leu
  const todos = ev.filter(e => e.seq > desde);
  truncado = todos.length > limit;
  out = todos.slice(0, limit);
} else {
  out = ev.slice(-limit);
}
msg.statusCode = 200;
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { ok: true, flow: FLOW, boot: boot, total: ev.length, ultimo: seq, descartados: drop, perdidos: perdidos, truncado: truncado, lidoEm: new Date().toISOString(), eventos: out };
return msg;

// dev-logs-v1.0 · POST /api/dev/logs/limpar
// Esvazia o buffer. 'seq' e 'ult' (sessao->n) continuam: o HTML não consegue reenviar o backlog antigo e ressuscitar o que foi limpo.
const ev = flow.get('devlog_ev') || [];
const n = ev.length;
flow.set('devlog_ev', []);
flow.set('devlog_drop', 0);
msg.statusCode = 200;
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { ok: true, flow: 'dev-logs-v1.0', limpos: n, ultimoSeq: flow.get('devlog_seq') || 0 };
return msg;

// dev-logs-v1.0 · captura qualquer exceção dos nós desta aba e responde 500 (a requisição não fica pendurada)
msg.statusCode = 500;
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { ok: false, flow: 'dev-logs-v1.0', erro: (msg.error && msg.error.message) || 'erro interno' };
return msg;

// PORTAO 3 (D3) - "Nunca confie no cliente": rota de ESCRITA so aceita pedido que veio da PROPRIA tela e em JSON.
// CORS sozinho NAO protege (o browser envia o POST mesmo assim); por isso o servidor confere Origin/Referer e Content-Type.
// Origem permitida = mesmo host da pagina (cabecalho Host) ou item de BT2_ORIGENS_OK (variavel da ABA, ex.: http://servidor:1880,null).
const h = (msg.req && msg.req.headers) || {};
const host = String(h.host || '').toLowerCase();
const extras = String(env.get('BT2_ORIGENS_OK') || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const hostDe = u => { try { return new URL(String(u)).host.toLowerCase(); } catch (e) { return null; } };
const origemDe = u => { try { return new URL(String(u)).origin.toLowerCase(); } catch (e) { return null; } };
let motivo = null;
if (h.origin !== undefined) {
  const o = String(h.origin).toLowerCase();
  if (!((host && hostDe(o) === host) || extras.includes(o))) motivo = 'origem_nao_permitida';
} else if (h.referer !== undefined) {
  const r = origemDe(h.referer);
  if (!((host && hostDe(h.referer) === host) || (r && extras.includes(r)))) motivo = 'origem_nao_permitida';
} else {
  motivo = 'sem_origem';
}
if (!motivo && !/^application\/json\s*(;|$)/i.test(String(h['content-type'] || ''))) motivo = 'content_type_invalido';
if (motivo) {
  node.warn('D3 bloqueado: ' + motivo + ' | ' + String((msg.req && msg.req.method) || '') + ' ' + String((msg.req && msg.req.url) || '').slice(0, 80) + ' | origin=' + String(h.origin || h.referer || '-').slice(0, 80));
  msg.statusCode = 403;
  msg.payload = { ok: false, codigo: 'D3_' + motivo, erro: 'pedido recusado: so e aceito da propria tela do medidor, em JSON (' + motivo + ')' };
  return [null, msg];
}
return [msg, null];

